//! Grapheme cluster segmentation and width, the way the terminal prints with mode 2027.
//!
//! Ghostty: `src/unicode/grapheme.zig` at `LIBGHOSTTY_VT_REV`, with uucode 0.2.0 @ `9d555245`'s
//! `grapheme.BreakState`.
//! rustty: `crates/rustty-unicode/src/grapheme.rs` at `RUSTTY_REV` (MIT).
//! Changes: `BreakState` is stored as the `u3` bit pattern uucode's packed struct has (`base * 2 + after_linker`),
//! which the precompute table indexes with directly; uucode's deprecated `.default` alias is `Default`. The
//! precompute table is the generated bytes (`gen-unicode` computes them with its port of uucode's rules), decoded at
//! compile time into one `static`. `graphemeWidth` is not generic: its code points are `u32`, so the
//! out-of-range guards Ghostty compiles in for types wider than `u21` are always on. The debug `main`, which sweeps
//! every pair of code points against uucode, has no counterpart: the generator checks the table against uucode's
//! `GraphemeBreakTest.txt` tests instead, on every run.

use crate::unicode::generated::grapheme_data;
use crate::unicode::props::GraphemeBreakNoControl;
use crate::unicode::props_table::table;

/// The grapheme break state carried between calls to [`grapheme_break`]: uucode's `BreakState`, a
/// `packed struct(u3) { after_linker: bool, base: Base }`.
///
/// `GB9c` can overlap `GB11`: after `ExtPict Linker`, `Extend* ZWJ ExtPict` is still an emoji ZWJ sequence while
/// `Extend* Consonant` is still a conjunct. So "after a linker" is tracked beside `base` rather than as a state of its
/// own. The packed layout gives `base * 2 + after_linker`; with `RegionalIndicator` last in [`Base`], the one
/// combination that never occurs (a regional indicator after a linker) is the highest value, so the precomputed
/// table leaves it out.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub(crate) struct BreakState(u8);

/// `BreakState.Base` (`enum(u2)`).
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
#[repr(u8)]
pub(crate) enum Base {
    #[default]
    Default = 0,
    ExtendedPictographic = 1,
    RegionalIndicator = 2,
}

impl BreakState {
    /// The number of states the precomputed table has rows for (`table_len`): every `Base` with and without
    /// `after_linker`, less the one combination that never occurs.
    pub(crate) const TABLE_LEN: usize = 3 * 2 - 1;

    /// `BreakState { .after_linker = after_linker, .base = base }`.
    pub(crate) const fn new(after_linker: bool, base: Base) -> Self {
        Self((after_linker as u8) | ((base as u8) << 1))
    }

    /// The `after_linker` field.
    pub(crate) const fn after_linker(self) -> bool {
        (self.0 & 1) != 0
    }

    /// The `base` field.
    pub(crate) const fn base(self) -> Base {
        match self.0 >> 1 {
            0 => Base::Default,
            1 => Base::ExtendedPictographic,
            _ => Base::RegionalIndicator,
        }
    }

    /// The state's row in the precomputed table (`tableIndex`).
    pub(crate) const fn table_index(self) -> usize {
        self.0 as usize
    }

    /// The state of a table row (`fromTableIndex`). Only the precompute decode calls it, at compile time, where a
    /// row past [`Self::TABLE_LEN`] or past the generated bytes' `u3` fails the build (Zig's illegal `@intCast`).
    const fn from_table_index(i: u8) -> Self {
        assert!((i as usize) < Self::TABLE_LEN);
        Self(i)
    }
}

/// Whether there is a grapheme break between two code points. Call it sequentially, keeping `state` between calls.
///
/// It does NOT work with control characters: controls, line feeds and carriage returns are filtered out before it
/// is called, which is what Ghostty tunes it for.
#[inline]
pub(crate) fn grapheme_break(cp1: u32, cp2: u32, state: &mut BreakState) -> bool {
    let key = Key {
        state: *state,
        gb1: table().get(cp1).grapheme_break,
        gb2: table().get(cp2).grapheme_break,
    };
    let value = PRECOMPUTE[key.index()];
    *state = value.state;
    value.result
}

/// The width change a code point asks for when it continues a grapheme cluster.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum GraphemeWidthEffect {
    /// Do not append the code point to the cluster, and leave the break state as it was before it.
    Ignore,
    /// Append the code point and leave the cluster's width unchanged.
    NoChange,
    /// Make the cluster two cells wide.
    Wide,
    /// Make the cluster one cell wide.
    Narrow,
}

/// The first grapheme cluster of a code point slice, measured.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct GraphemeWidth {
    /// The number of code points consumed from the slice.
    pub(crate) len: usize,
    /// The display width in cells.
    pub(crate) width: u8,
}

/// The width effect of appending `cp` after `prev` within a grapheme.
///
/// The width decision shared by the terminal's streaming printer and [`grapheme_width`]. It assumes
/// [`grapheme_break`] already said there is no break between `prev` and `cp`; it does no segmentation.
///
/// `Ignore` matters for invalid emoji variation selectors: the terminal does not store them in the cell, so a caller
/// seeing it also restores its break state and keeps `prev`.
#[inline]
pub(crate) fn grapheme_width_effect(prev: u32, cp: u32) -> GraphemeWidthEffect {
    // VS16 makes a valid emoji variation base wide and VS15 makes it narrow (emoji-variation-sequences.txt); after
    // anything else the selector is ignored entirely.
    if cp == 0xFE0F || cp == 0xFE0E {
        if !table().get(prev).emoji_vs_base {
            return GraphemeWidthEffect::Ignore;
        }
        return if cp == 0xFE0F {
            GraphemeWidthEffect::Wide
        } else {
            GraphemeWidthEffect::Narrow
        };
    }

    // A code point that contributes to the width makes the whole grapheme at least 2 wide, because the first code
    // point is at least 1 wide to start it. Prepend code points could mean the first one should be width 0, which is
    // not handled yet.
    if !table().get(cp).width_zero_in_grapheme {
        return GraphemeWidthEffect::Wide;
    }

    GraphemeWidthEffect::NoChange
}

/// Whether a `u32` is past Unicode's range.
const fn invalid_codepoint(cp: u32) -> bool {
    cp > 0x10_FFFF
}

/// The first grapheme cluster of `cps`, measured with the segmentation and width rules of the terminal's print with
/// mode 2027.
///
/// Not a streaming API: `cps` holds a complete first cluster or the logical end of the text. When code points arrive
/// in chunks, keep buffering while this consumes everything and more may come.
///
/// Values above U+10FFFF are accepted: one that starts the slice is a cluster of its own, one code point at width 1;
/// one later in the slice ends the cluster before it.
pub(crate) fn grapheme_width(cps: &[u32]) -> GraphemeWidth {
    let Some(&first) = cps.first() else {
        return GraphemeWidth { len: 0, width: 0 };
    };
    if invalid_codepoint(first) {
        return GraphemeWidth { len: 1, width: 1 };
    }

    let mut len = 1;
    let mut width = table().get(first).width;
    let mut prev = first;
    let mut state = BreakState::default();
    for &cp in &cps[1..] {
        if invalid_codepoint(cp) {
            break;
        }
        let state_before = state;
        if grapheme_break(prev, cp, &mut state) {
            break;
        }
        match grapheme_width_effect(prev, cp) {
            GraphemeWidthEffect::Ignore => state = state_before,
            GraphemeWidthEffect::NoChange => prev = cp,
            GraphemeWidthEffect::Wide => {
                width = 2;
                prev = cp;
            }
            GraphemeWidthEffect::Narrow => {
                width = 1;
                prev = cp;
            }
        }
        len += 1;
    }
    GraphemeWidth { len, width }
}

/// A key of the precomputed table: uucode's `packed struct(u13) { state: u3, gb1: u5, gb2: u5 }`, whose bit
/// pattern is the index.
struct Key {
    state: BreakState,
    gb1: GraphemeBreakNoControl,
    gb2: GraphemeBreakNoControl,
}

impl Key {
    fn index(&self) -> usize {
        self.state.table_index() | ((self.gb1 as usize) << 3) | ((self.gb2 as usize) << 8)
    }
}

/// A value of the precomputed table: whether there is a break, and the state after it (`packed struct(u8)`).
#[derive(Clone, Copy)]
struct Value {
    result: bool,
    state: BreakState,
}

/// The precomputed table for every permutation of state and grapheme break properties: 2^13 keys, one value each.
/// One `static`, so every caller reads the same object, as Zig's container-level constant is one.
static PRECOMPUTE: [Value; 8192] = decode_precompute(&grapheme_data::DATA);

/// The table's values from the generated bytes (`result | state << 1`). The table never hands back a state it has no
/// row for; a key that cannot occur is zero.
const fn decode_precompute(bytes: &[u8; 8192]) -> [Value; 8192] {
    let mut out = [Value {
        result: false,
        state: BreakState(0),
    }; 8192];
    let mut i = 0;
    while i < bytes.len() {
        out[i] = Value {
            result: (bytes[i] & 1) != 0,
            state: BreakState::from_table_index(bytes[i] >> 1),
        };
        i += 1;
    }
    out
}

